import { HttpError } from "wasp/server";
import { defineUserSignupFields } from "wasp/server/auth";
import type { OnBeforeSignupHook } from "wasp/server/auth";

export const userSignupFields = defineUserSignupFields({
  role: (data) => {
    const validRoles = ["ANALYST", "MANAGER", "ADMIN"];
    if (typeof data.role === "string" && validRoles.includes(data.role)) {
      return data.role;
    }
    return "ANALYST";
  },
});

export const onBeforeSignup: OnBeforeSignupHook = async ({
  providerId,
  prisma,
  req,
}) => {
  const username = providerId.providerUserId;
  const role = req.body?.role;

  if (role === "ADMIN") {
    if (!username || !username.endsWith("_admin")) {
      throw new HttpError(
        400,
        "Users signing up with the ADMIN role must have a username ending with _admin"
      );
    }
  }
};

import { HttpError } from "wasp/server";
import type {
  GetDocuments,
  GetAuditLogs,
  CreateDocument,
  UpdateDocument,
  DeleteDocument,
} from "wasp/server/operations";

export const getDocuments: GetDocuments<void, any> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  return context.entities.Document.findMany({
    include: {
      owner: true,
    },
  });
};

export const getAuditLogs: GetAuditLogs<void, any> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  if (context.user.role !== "ADMIN") {
    throw new HttpError(403, "Access denied. Only ADMINs can view audit logs.");
  }
  return context.entities.AuditLog.findMany({
    orderBy: { timestamp: "desc" },
  });
};

export const createDocument: CreateDocument<
  { title: string; content: string },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  const role = context.user.role;
  if (role !== "MANAGER" && role !== "ADMIN") {
    throw new HttpError(
      403,
      "Access denied. Only MANAGERs and ADMINs can create documents."
    );
  }

  const document = await context.entities.Document.create({
    data: {
      title: args.title,
      content: args.content,
      ownerId: context.user.id,
    },
  });

  await context.entities.AuditLog.create({
    data: {
      action: "CREATE",
      entityName: "Document",
      entityId: document.id,
      userId: context.user.id,
      payload: JSON.stringify({ title: args.title, content: args.content }),
    },
  });

  return document;
};

export const updateDocument: UpdateDocument<
  { id: number; title: string; content: string },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  const role = context.user.role;
  if (role !== "MANAGER" && role !== "ADMIN") {
    throw new HttpError(
      403,
      "Access denied. Only MANAGERs and ADMINs can update documents."
    );
  }

  const document = await context.entities.Document.update({
    where: { id: args.id },
    data: {
      title: args.title,
      content: args.content,
    },
  });

  await context.entities.AuditLog.create({
    data: {
      action: "UPDATE",
      entityName: "Document",
      entityId: document.id,
      userId: context.user.id,
      payload: JSON.stringify({ title: args.title, content: args.content }),
    },
  });

  return document;
};

export const deleteDocument: DeleteDocument<{ id: number }, any> = async (
  args,
  context
) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  const role = context.user.role;
  if (role !== "ADMIN") {
    throw new HttpError(
      403,
      "Access denied. Only ADMINs can delete documents."
    );
  }

  const document = await context.entities.Document.delete({
    where: { id: args.id },
  });

  await context.entities.AuditLog.create({
    data: {
      action: "DELETE",
      entityName: "Document",
      entityId: args.id,
      userId: context.user.id,
      payload: JSON.stringify({ id: args.id }),
    },
  });

  return document;
};

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { userSignupFields, onBeforeSignup } from "./src/auth" with { type: "ref" };
import {
  getDocuments,
  getAuditLogs,
  createDocument,
  updateDocument,
  deleteDocument,
} from "./src/operations" with { type: "ref" };

export default app({
  name: "app",
  title: "Wasp RBAC & Audit Logging Enterprise App",
  wasp: { version: "^0.24.0" },
